function rawHandshake(host, port) {
  return new Promise((resolve, reject) => {
    const key = crypto.randomBytes(16).toString('base64');
    const req = http.request({
      host, port, path: '/', method: 'GET',
      headers: {
        Connection: 'Upgrade', Upgrade: 'websocket',
        'Sec-WebSocket-Key': key, 'Sec-WebSocket-Version': '13',
      },
    });
    req.on('upgrade', (res, socket) => {
      const expected = crypto.createHash('sha1')
        .update(key + '258EAFA5-E914-47DA-95CA-C5AB0DC85B11').digest('base64');
      resolve({ status: res.statusCode, headers: res.headers, acceptOk: res.headers['sec-websocket-accept'] === expected, socket });
    });
    req.on('error', reject);
    req.setTimeout(5000, () => req.destroy(new Error('handshake timeout')));
    req.end();
  });
}

